def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    # Exterior zeros are flood-filled from the border; holes are the remaining zero regions.
    zseen=set(); holes=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=0 or (r,c) in zseen: continue
        q=[(r,c)]; zseen.add((r,c)); reg=[]; edge=False
        for x,y in q:
          reg.append((x,y)); edge |= x==0 or y==0 or x==h-1 or y==w-1
          for dx,dy in dirs:
            a,b=x+dx,y+dy
            if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in zseen:
              zseen.add((a,b)); q.append((a,b))
